using System;using System.Collections;using System.Collections.Generic;using System.Globalization;using System.IO;using UnityEngine;using UnityEditor;using Unity.Profiling;
public sealed class RetroExperimentProbe:MonoBehaviour {
 public static bool Finished;public static List<string> Results=new List<string>();public static string Progress="";int failures;
 const string Root="Assets/MapTests/RetroStyle";
 void Check(bool ok,string name){Results.Add((ok?"PASS ":"FAIL ")+name);if(!ok)failures++;}
 public static void StartTests(){Finished=false;Results.Clear();var runner=new GameObject("RetroStyle verification — temporal").AddComponent<RetroExperimentProbe>();runner.StartCoroutine(runner.Run());}
 static int Hash(Texture2D image){var colors=image.GetPixels32();int hash=17;for(int i=0;i<colors.Length;i+=17)hash=unchecked(hash*31+colors[i].GetHashCode());return hash;}
 IEnumerator Run(){var e=UnityEngine.Object.FindAnyObjectByType<RetroDungeonExperiment>();e.acceptInput=false;e.showControls=false;e.showMiniMap=false;Directory.CreateDirectory(Root+"/Captures");var games=UnityEngine.Object.FindObjectsByType<DungeonPrototype>(UnityEngine.FindObjectsInactive.Include);bool isolated=games.Length==1&&!games[0].enabled&&games[0].gameObject==e.gameObject&&games[0].transform.childCount==1;Check(isolated,"Arranque original bloqueado: solo marcador desactivado, sin geometría ni cámara del juego");Check(e!=null&&e.map.Valid,"Escena abre con cuadrícula existente válida");e.SetMode(RetroExperimentMode.Pseudo3DDrawn);e.maximumDistance=e.depthLevels=10;e.SetResolution(256,192);e.SetDoor("retro.door",false);e.SetPose(new Vector2Int(3,2),0);int initial=Hash(e.Canvas.Image);Check(e.Step(1)&&e.Position==new Vector2Int(3,3)&&Hash(e.Canvas.Image)!=initial,"Avanzar cambia composición y posición exactamente una casilla");initial=Hash(e.Canvas.Image);e.Turn(1);Check(e.Heading==1&&Hash(e.Canvas.Image)!=initial,"Giro90 actualiza perspectiva");e.Turn(-1);Check(e.Heading==0,"Giro inverso restaura orientación");Check(e.Step(-1)&&e.Position==new Vector2Int(3,2),"Retroceder una casilla");e.SetPose(new Vector2Int(3,1),2);Check(!e.Step(1)&&e.Position==new Vector2Int(3,1),"Pared bloquea movimiento");e.SetPose(new Vector2Int(10,12),0);initial=Hash(e.Canvas.Image);Check(!e.Step(1),"Puerta cerrada bloquea movimiento");Check(e.ToggleFacingDoor()&&e.DoorOpen("retro.door")&&Hash(e.Canvas.Image)!=initial,"Puerta abierta cambia composición");Check(e.Step(1)&&e.Position==new Vector2Int(10,13),"Puerta abierta permite pasar");
  var enemy=e.decorations[0];Vector2Int original=enemy.cell;enemy.cell=new Vector2Int(3,7);e.SetPose(new Vector2Int(3,3),0);Check(e.Canvas.VisiblePixels(1)>0,"Sprite enemigo visible en pasillo");int farPixels=e.Canvas.VisiblePixels(1);e.SetPose(new Vector2Int(3,5),0);Check(e.Canvas.VisiblePixels(1)>farPixels,"Sprite aumenta de tamaño al acercarse");enemy.cell=new Vector2Int(3,9);e.SetPose(new Vector2Int(3,2),0);Check(e.Canvas.VisiblePixels(1)==0,"Pared oculta enemigo situado detrás");enemy.cell=new Vector2Int(10,14);e.SetPose(new Vector2Int(10,12),0);e.SetDoor("retro.door",false);Check(e.Canvas.VisiblePixels(1)==0,"Puerta cerrada oculta sprite");e.SetDoor("retro.door",true);Check(e.Canvas.VisiblePixels(1)>0,"Abrir puerta descubre sprite");enemy.cell=original;e.SetPose(new Vector2Int(10,8),0);Check(e.Canvas.VisiblePixels(2)>0,"Objeto de muestra visible dentro de habitación");
  int count=e.Canvas.Compositions;for(int f=0;f<20;f++)yield return null;Check(e.Canvas.Compositions==count,"No recompone ni crea texturas por frame en reposo");e.SetResolution(426,240);Check(e.Canvas.Image.width==426&&e.Canvas.Image.height==240&&e.Canvas.Image.filterMode==FilterMode.Point,"Resolución426×240, Point, sin mipmaps");e.SetResolution(256,192);Check(e.Canvas.Image.mipmapCount==1,"Imagen sin antialiasing ni mipmaps");
  Vector2Int[] poses={new Vector2Int(3,3),new Vector2Int(3,8),new Vector2Int(10,13),new Vector2Int(10,16),new Vector2Int(10,12),new Vector2Int(10,12)};int[] headings={0,1,1,0,0,0};string[] names={"Straight","Corner","Intersection","WideRoom","DoorClosed","DoorOpen"};for(int mode=0;mode<2;mode++){e.SetMode(mode==0?RetroExperimentMode.Pseudo3DDrawn:RetroExperimentMode.Current3DReference);for(int i=0;i<poses.Length;i++){Progress="Captura "+mode+" / "+names[i];e.SetPose(poses[i],headings[i]);e.SetDoor("retro.door",i==5);for(int f=0;f<5;f++)yield return null;e.SaveImage(Root+"/Captures/"+(mode==0?"C-":"A-")+names[i]+".png");if(mode==0)Check(e.Canvas.BackgroundPixels()==0,names[i]+": superficies encajan sin huecos");}if(mode==1)Check(e.ReferenceTexture.IsCreated()&&e.referenceCamera.enabled&&e.referenceCamera.gameObject.activeInHierarchy,"Cámara3D independiente con RenderTexture válida");}
  var performance=new List<string>{"mode,resolution,frames,fps,frame_ms,cpu_playerloop_ms,gpu_ms,draw_calls,setpass,gc_bytes_frame,recompose_ms,buffer_bytes"};foreach(var resolution in new[]{new Vector2Int(256,192),new Vector2Int(426,240)})foreach(var mode in new[]{RetroExperimentMode.Pseudo3DDrawn,RetroExperimentMode.Current3DReference}){Progress="Rendimiento "+mode+" "+resolution;e.SetResolution(resolution.x,resolution.y);e.SetMode(mode);e.SetPose(new Vector2Int(10,16),0);for(int f=0;f<30;f++)yield return null;var gc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame");var cpu=UnityEngine.Profiling.Recorder.Get("PlayerLoop");cpu.enabled=true;double elapsed=0,cpuMs=0,gpuMs=0,gcBytes=0,calls=0,passes=0;int gpuCount=0;var timing=new FrameTiming[1];const int frames=120;for(int f=0;f<frames;f++){yield return null;elapsed+=Time.unscaledDeltaTime;cpuMs+=cpu.isValid?cpu.elapsedNanoseconds/1000000.0:0;gcBytes+=gc.Valid?gc.LastValue:0;calls+=UnityStats.drawCalls;passes+=UnityStats.setPassCalls;FrameTimingManager.CaptureFrameTimings();if(FrameTimingManager.GetLatestTimings(1,timing)>0&&timing[0].gpuFrameTime>0){gpuMs+=timing[0].gpuFrameTime;gpuCount++;}}performance.Add(mode+","+resolution.x+"x"+resolution.y+","+frames+","+(frames/elapsed).ToString("F2",CultureInfo.InvariantCulture)+","+(elapsed*1000/frames).ToString("F3",CultureInfo.InvariantCulture)+","+(cpuMs/frames).ToString("F3",CultureInfo.InvariantCulture)+","+(gpuCount>0?(gpuMs/gpuCount).ToString("F3",CultureInfo.InvariantCulture):"unavailable")+","+(calls/frames).ToString("F2",CultureInfo.InvariantCulture)+","+(passes/frames).ToString("F2",CultureInfo.InvariantCulture)+","+(gcBytes/frames).ToString("F0",CultureInfo.InvariantCulture)+","+e.Canvas.LastMilliseconds.ToString("F3",CultureInfo.InvariantCulture)+","+e.ApproximateImageBytes);gc.Dispose();}
  File.WriteAllLines(Root+"/Performance.csv",performance);e.SetResolution(256,192);e.SetMode(RetroExperimentMode.Pseudo3DDrawn);e.SetDoor("retro.door",false);e.SetPose(e.map.startCell,e.map.startHeading);e.acceptInput=true;e.showControls=e.showMiniMap=true;Results.Add("TOTAL "+(Results.Count-failures)+" PASS / "+failures+" FAIL");File.WriteAllLines(Root+"/McpResults.txt",Results);Progress="Finalizado";Finished=true;Destroy(gameObject);
 }
}
